create table if not exists director_schema_migrations (name text primary key, applied_at timestamptz not null default now());
create table if not exists director_events (event_id uuid primary key, event_type text not null, occurred_at timestamptz not null, ingested_at timestamptz not null default now(), source_system text not null, source_reference jsonb not null default '{}', project_ref jsonb not null, person_ref jsonb, correlation_id uuid not null, causation_id uuid, idempotency_key text not null unique, payload jsonb not null, provenance jsonb not null);
create table if not exists director_obligations (id uuid primary key, owner_ref jsonb not null, project_ref jsonb not null, person_ref jsonb, source_event_id uuid not null references director_events(event_id), kind text not null, summary text not null, status text not null, created_at timestamptz not null default now(), due_at timestamptz, resolved_at timestamptz, importance integer not null, confidence double precision not null, provenance jsonb not null, version integer not null default 1, check ((status = 'RESOLVED') = (resolved_at is not null)));
create table if not exists director_decisions (id uuid primary key, obligation_id uuid not null unique references director_obligations(id), question text not null, options jsonb not null, status text not null, requested_at timestamptz not null, required_by timestamptz, decided_at timestamptz, decided_by jsonb, selected_option text, rationale text, provenance jsonb not null, version integer not null default 1);
create table if not exists director_open_loops (id uuid primary key, obligation_id uuid references director_obligations(id), project_ref jsonb not null, person_ref jsonb, expected_result text not null, status text not null, opened_at timestamptz not null, expected_by timestamptz, closed_at timestamptz, source_event_id uuid references director_events(event_id), provenance jsonb not null);
create table if not exists director_timeline (id uuid primary key, occurred_at timestamptz not null, event_type text not null, actor_type text not null, actor_ref jsonb, project_ref jsonb not null, person_ref jsonb, description text not null, source_system text not null, source_ref jsonb, correlation_id uuid not null, provenance jsonb not null);
create index if not exists director_obligations_active_idx on director_obligations(status, due_at);
create index if not exists director_timeline_project_idx on director_timeline using gin(project_ref);
